 private offerButton(id:string,label:string,r:Rect,offer:PublicActionOffer|PublicTargetOffer|undefined,activate:()=>void){const disabled=!offer||offer.status==='disabled'||this.state.blocked;this.button(id,label,r,()=>{if(!disabled)activate();else{this.hint=this.t(offer?.publicReason??'interaction.unavailable');this.invalidate();}});if(disabled){this.ctx.fillStyle='#0a182699';this.ctx.fillRect(r.x,r.y,r.width,r.height);}else if(offer.status==='uncertain'){this.ctx.strokeStyle='#d5aa54';this.ctx.strokeRect(r.x+1,r.y+1,r.width-2,r.height-2);}}
